// Loads real SEC season data from the Flask backend (which proxies/caches the
// ncaa.com NCAA API). Teams + schedules come up front; team stats and game box
// scores are fetched lazily and memoized, since each is an expensive crawl.

const _teamCache = {};
const _gameCache = {};
const _playerCache = {};
const _rosterCache = {};

// One team's roster, read from the static 2026/<Team>/roster.txt file
// (generated by build_roster.py). Returns [{num,name,pos,role,g}, ...].
window.fetchRoster = function (seo) {
  if (!_rosterCache[seo]) {
    _rosterCache[seo] = fetch("/api/roster/" + encodeURIComponent(seo))
      .then((r) => {
        if (!r.ok) throw new Error("roster " + r.status);
        return r.json();
      });
  }
  return _rosterCache[seo];
};

// One player's per-season totals + game log, from the local 2026/ folders.
window.fetchPlayer = function (seo, playerName) {
  const key = seo + "::" + playerName;
  if (!_playerCache[key]) {
    _playerCache[key] = fetch(
      "/api/player/" + encodeURIComponent(seo) +
      "?player=" + encodeURIComponent(playerName)
    ).then((r) => {
      if (!r.ok) throw new Error("player " + r.status);
      return r.json();
    });
  }
  return _playerCache[key];
};

// A league label ("NCAA" / "SEC" / "ACC") -> the backend's ?league= value.
function _leagueSeo(league) {
  return (league || window.CURRENT_LEAGUE || "SEC").toLowerCase().replace(/\s+/g, "-");
}

// Memoize the per-league aggregation fetches, keyed by league (so switching
// leagues fetches once per league and caches).
function _memoFetch(cacheName, urlBase, errLabel) {
  return function (league) {
    const seo = _leagueSeo(league);
    const cache = (window[cacheName] = window[cacheName] || {});
    if (!cache[seo]) {
      cache[seo] = fetch(urlBase + "?league=" + encodeURIComponent(seo)).then((r) => {
        if (!r.ok) throw new Error(errLabel + " " + r.status);
        return r.json();
      });
    }
    return cache[seo];
  };
}

// Official D1 Top 25 poll (for the NCAA standings view). League-independent.
window.fetchTop25 = function () {
  if (!window.__top25Cache) {
    window.__top25Cache = fetch("/api/rankings/top25").then((r) => {
      if (!r.ok) throw new Error("top25 " + r.status);
      return r.json();
    });
  }
  return window.__top25Cache;
};

// Conference stat leaders (top 3 in AVG/HR/ERA across the league's teams).
window.fetchConferenceLeaders = _memoFetch("__clCache", "/api/conference-leaders", "conference-leaders");
window.fetchRankingsHistory = _memoFetch("__rankHistCache", "/api/rankings/history", "rankings-history");
window.fetchPlayerOfWeek = _memoFetch("__potwCache", "/api/player-of-week", "player-of-week");
// Players to watch — top batters + pitchers (one per team) by the player-of-week formula.
window.fetchPlayersToWatch = _memoFetch("__ptwCache", "/api/players-to-watch", "players-to-watch");

window.fetchTeam = function (seo) {
  if (!_teamCache[seo]) {
    _teamCache[seo] = fetch("/api/team/" + encodeURIComponent(seo)).then((r) => {
      if (!r.ok) throw new Error("team " + r.status);
      return r.json();
    });
  }
  return _teamCache[seo];
};

// Pass the host team + date + the host's run total so the backend can match
// this game to a locally-saved 2026/ folder (real play-by-play); it falls back
// to the ncaa.com API when there's no local copy.
window.fetchGame = function (game, hostTeamId) {
  const runs = game.score ? game.score.us : "";
  const oppSeo = (game.opp && game.opp.id) || "";
  const qs =
    "?team=" + encodeURIComponent(hostTeamId || "") +
    "&iso=" + encodeURIComponent(game.iso || "") +
    "&runs=" + encodeURIComponent(runs) +
    "&opp=" + encodeURIComponent(oppSeo);
  const key = game.id + qs;
  if (!_gameCache[key]) {
    _gameCache[key] = fetch(
      "/api/game/" + encodeURIComponent(game.id) + qs
    ).then((r) => {
      if (!r.ok) throw new Error("game " + r.status);
      return r.json();
    });
  }
  return _gameCache[key];
};

window.__bootstrapReady = fetch("/api/bootstrap")
  .then((res) => {
    if (!res.ok) throw new Error("bootstrap " + res.status);
    return res.json();
  })
  .then((d) => {
    window.TEAMS = d.teams;
    window.TEAM_BY_ID = Object.fromEntries(d.teams.map((t) => [t.id, t]));
    window.SCHEDULES = d.schedules;
    // Leagues for the top-bar selector: "NCAA" (all teams) + each conference that
    // has data, sorted. window.leagueTeams(league) returns the scoped team list;
    // TEAMS/TEAM_BY_ID/SCHEDULES stay COMPLETE so cross-conference lookups work.
    const _confs = Array.from(new Set(d.teams.map((t) => t.conference).filter(Boolean))).sort();
    window.LEAGUES = ["NCAA"].concat(_confs);
    window.leagueTeams = function (league) {
      if (!league || league === "NCAA") return window.TEAMS;
      return window.TEAMS.filter((t) => t.conference === league);
    };
    window.SEASON_UPDATED = d.updated;
    window.SEASON_PHASE = d.phase;   // { phase: "super_regionals", label: "Super Regionals" }
    window.SUPER_REGIONALS = d.super_regionals || [];  // [{ id, top:{seo,name,logo,seed}, bottom:{...}, city }]
    window.REGIONAL_CITY_BY_TEAM = d.regional_cities || {};  // { team_seo: host_city } — name a regional by host city
    window.SEASON_CLOCK = d.clock || {};   // { override: "2026-05-15"|null, today: "2026-06-03" } — dev time machine
  })
  .catch((err) => {
    document.getElementById("root").innerHTML =
      '<div style="padding:48px;font-family:sans-serif;color:#74808a">' +
      "Failed to load season data: " +
      err.message +
      ". Is the Flask server running?</div>";
    throw err;
  });
